    Customer Support Process

        body {
            font-family: Arial, sans-serif;
            background-color: #f4f4f4;
            padding: 10px;
        }

        .process-container {
            width: 420px;
            margin: 0;
            background-color: white;
            padding: 5px;
            border-radius: 10px;
            box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
        }

table, th, td {
  border: 0px solid red;
}

        table {
            border-collapse: collapse;
            margin: auto;

        }

        th {
padding: 0;
            margin: 0;
            vertical-align: bottom;
	    position: relative;
        }

        td {
            padding: 0;
            margin: auto;
            vertical-align: middle;
	    position: relative;
text-align: center;
        }

img {
height: 30px;
width: 30px;
  display: block;
margin: auto;
}

        .label {
            font-size: 10px;
            color: #000000;
            font-weight: bold;
        }

        .arrow-right {
            font-size: 24px;
            color: #000000;
        }










